def nth_good_integer(N: int) -> int:
    def is_good_integer(num: int) -> bool:
        # Check if all digits of the number are even
        while num > 0:
            if (num % 10) % 2 != 0:
                return False
            num //= 10
        return True

    count = 0
    current = 0
    while count < N:
        if is_good_integer(current):
            count += 1
        if count < N:
            current += 1
    return current
